package rv.batch.format;import java.util.Locale;public class NumberFormat {protected final Locale locale;protected final String style;protected int min=-1,max=-1;protected NumberFormat(Locale l,String s){locale=l;style=s;}public static NumberFormat getNumberInstance(){return new DecimalFormat(Locale.getDefault(),"decimal");}public static NumberFormat getPercentInstance(Locale l){return new DecimalFormat(l,"percent");}public void setMaximumFractionDigits(int n){max=n;}public void setMinimumFractionDigits(int n){min=n;}public String format(long n){return render(Long.valueOf(n));}public String format(double n){return render(Double.valueOf(n));}protected String render(Number n){return (String)rv.batch.Platform.invoke("format.number",n,locale.toLanguageTag(),style,min,max,this instanceof DecimalFormat&&((DecimalFormat)this).symbols!=null?((DecimalFormat)this).symbols.getDigitStrings():null);}}
